from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def calculate_depth(paren_set: str) -> int:
        max_depth = 0
        current_depth = 0
        for char in paren_set:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        return max_depth

    sets = paren_string.split()
    depths = [calculate_depth(paren_set) for paren_set in sets]

    return depths

